import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

/* IMAGE HELPER */
const getImage = (product) => {
  const name = (product.productName || "").toLowerCase();

  // VEGETABLES
  if (name.includes("broccoli")) {
    return "https://images.unsplash.com/photo-1459411621453-7b03977f4bfc?w=600&q=80";
  }

  if (name.includes("carrot")) {
    return "https://images.unsplash.com/photo-1447175008436-054170c2e979?w=600&q=80";
  }

  if (name.includes("beetroot") || name.includes("beet")) {
    return "https://images.unsplash.com/photo-1518977676601-b53f82aba655?w=600&q=80";
  }

  // SNACKS
  if (name.includes("dates")) {
    return "https://images.unsplash.com/photo-1603048719539-9ecb4bcb2393?w=600&q=80";
  }

  if (name.includes("walnut")) {
    return "https://images.unsplash.com/photo-1615485290382-441e4d049cb5?w=600&q=80";
  }

  // PROTEINS
  if (name.includes("protein")) {
    return "https://images.unsplash.com/photo-1593095948071-474c5cc2989d?w=600&q=80";
  }

  // DRINKS
  if (name.includes("juice") || name.includes("drink")) {
    return "https://images.unsplash.com/photo-1544145945-f90425340c7e?w=600&q=80";
  }

  // DEFAULT
  return "https://images.unsplash.com/photo-1542838132-92c53300491e?w=600&q=80";
};

const CATEGORIES = [
  "All",
  "Proteins",
  "Vegetables",
  "Snacks",
  "Supplements",
  "Drinks",
];

const s = {
  page: {
    minHeight: "100vh",
    width: "100%",
    background: "#eef3f7",
    fontFamily: "'DM Sans', sans-serif",
  },

  nav: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    padding: "0 40px",
    height: "80px",
    background: "rgba(255,255,255,0.96)",
    backdropFilter: "blur(12px)",
    borderBottom: "1px solid #d4e8d4",
    position: "sticky",
    top: 0,
    zIndex: 100,
    boxShadow: "0 2px 20px rgba(15,123,46,0.08)",
  },

  logo: {
    fontFamily: "'Sora', sans-serif",
    fontWeight: 800,
    fontSize: "1.5rem",
    color: "#0f7b2e",
  },

  navLinks: {
    display: "flex",
    gap: "4px",
    alignItems: "center",
  },

  navBtn: {
    padding: "8px 16px",
    borderRadius: "50px",
    fontWeight: 500,
    fontSize: "0.88rem",
    color: "#1a2e1a",
    background: "transparent",
    border: "none",
    cursor: "pointer",
  },

  navBtnActive: {
    padding: "8px 16px",
    borderRadius: "50px",
    fontWeight: 600,
    fontSize: "0.88rem",
    color: "#0f7b2e",
    background: "#e6f4ea",
    border: "none",
    cursor: "pointer",
  },

  cartBtn: {
    padding: "8px 18px",
    borderRadius: "50px",
    fontWeight: 600,
    fontSize: "0.88rem",
    color: "#fff",
    background: "#0f7b2e",
    border: "none",
    cursor: "pointer",
    display: "flex",
    alignItems: "center",
    gap: "6px",
  },

  signoutBtn: {
    padding: "8px 16px",
    borderRadius: "50px",
    fontWeight: 500,
    fontSize: "0.88rem",
    color: "#888",
    background: "transparent",
    border: "1px solid #ddd",
    cursor: "pointer",
  },

  hero: {
    width: "100%",
    background:
      "linear-gradient(135deg, #0a2e14 0%, #0f5a26 50%, #1a8a40 100%)",
    padding: "72px 48px",
  },

  heroTitle: {
    fontFamily: "'Sora', sans-serif",
    fontSize: "3rem",
    fontWeight: 800,
    color: "#fff",
    lineHeight: 1.15,
    marginBottom: "14px",
  },

  heroSub: {
    color: "rgba(255,255,255,0.75)",
    fontSize: "1rem",
    lineHeight: 1.65,
    maxWidth: "480px",
  },

  shopBody: {
    padding: "32px 40px",
    maxWidth: "1400px",
    margin: "0 auto",
  },

  controls: {
    display: "flex",
    gap: "16px",
    alignItems: "center",
    marginBottom: "24px",
    flexWrap: "wrap",
  },

  searchInput: {
    width: "280px",
    padding: "11px 16px",
    borderRadius: "50px",
    border: "1.5px solid #d4e8d4",
    fontSize: "0.92rem",
    background: "#fff",
    outline: "none",
  },

  chips: {
    display: "flex",
    gap: "8px",
    flexWrap: "wrap",
  },

  chip: {
    padding: "7px 18px",
    borderRadius: "50px",
    border: "1.5px solid #d4e8d4",
    background: "#fff",
    fontSize: "0.82rem",
    fontWeight: 500,
    cursor: "pointer",
  },

  chipActive: {
    padding: "7px 18px",
    borderRadius: "50px",
    border: "1.5px solid #0f7b2e",
    background: "#0f7b2e",
    fontSize: "0.82rem",
    fontWeight: 600,
    cursor: "pointer",
    color: "#fff",
  },

  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))",
    gap: "20px",
  },

  card: {
    background: "#fff",
    borderRadius: "20px",
    overflow: "hidden",
    border: "1px solid #e8f0ea",
    boxShadow: "0 2px 16px rgba(15,123,46,0.07)",
    transition: "0.2s",
    display: "flex",
    flexDirection: "column",
  },

  img: {
    width: "100%",
    height: "200px",
    objectFit: "cover",
  },

  cardBody: {
    padding: "16px",
    display: "flex",
    flexDirection: "column",
    flex: 1,
  },

  catTag: {
    display: "inline-block",
    padding: "4px 10px",
    background: "#e6f4ea",
    color: "#0f7b2e",
    borderRadius: "50px",
    fontSize: "0.72rem",
    fontWeight: 700,
    marginBottom: "8px",
    textTransform: "uppercase",
  },

  productName: {
    fontFamily: "'Sora', sans-serif",
    fontWeight: 700,
    fontSize: "1rem",
    color: "#0a2e14",
    marginBottom: "4px",
  },

  brand: {
    fontSize: "0.82rem",
    color: "#888",
    marginBottom: "10px",
  },

  price: {
    fontFamily: "'Sora', sans-serif",
    fontWeight: 700,
    fontSize: "1.2rem",
    color: "#0f7b2e",
    marginBottom: "12px",
  },

  cardBtns: {
    display: "flex",
    gap: "8px",
    marginTop: "auto",
  },

  viewBtn: {
    flex: 1,
    padding: "10px",
    borderRadius: "50px",
    border: "1.5px solid #0f7b2e",
    background: "transparent",
    color: "#0f7b2e",
    fontWeight: 600,
    cursor: "pointer",
  },

  addBtn: {
    flex: 1,
    padding: "10px",
    borderRadius: "50px",
    border: "none",
    background: "#0f7b2e",
    color: "#fff",
    fontWeight: 600,
    cursor: "pointer",
  },
};

export default function Shop() {
  const navigate = useNavigate();

  const [products, setProducts] = useState([]);
  const [search, setSearch] = useState("");
  const [category, setCategory] = useState("All");

  useEffect(() => {
    axios
      .get("/products")
      .then((r) => setProducts(r.data))
      .catch(console.error);
  }, []);

  const filtered = products.filter((p) => {
    const matchSearch =
      (p.productName || "")
        .toLowerCase()
        .includes(search.toLowerCase()) ||
      (p.brand || "").toLowerCase().includes(search.toLowerCase());

    const matchCat =
      category === "All" ||
      (p.category || "").toLowerCase() === category.toLowerCase();

    return matchSearch && matchCat;
  });

  const addToCart = (product) => {
    const cart = JSON.parse(localStorage.getItem("cart") || "[]");

    const existing = cart.find(
      (i) => i.productID === product.productID
    );

    if (existing) {
      existing.quantity += 1;
    } else {
      cart.push({ ...product, quantity: 1 });
    }

    localStorage.setItem("cart", JSON.stringify(cart));

    alert(`${product.productName} added to cart`);
  };

  return (
    <div style={s.page}>
      {/* NAVBAR */}
      <nav style={s.nav}>
        <span style={s.logo}>🌿 NutriTrack</span>

        <div style={s.navLinks}>
          <button style={s.navBtnActive}>Shop</button>

          <button
            style={s.cartBtn}
            onClick={() => navigate("/cart")}
          >
            🛒 Cart
          </button>

          <button style={s.signoutBtn}>Sign Out</button>
        </div>
      </nav>

      {/* HERO */}
      <div style={s.hero}>
        <h1 style={s.heroTitle}>
          Fuel your body
          <br />
          with what it deserves
        </h1>

        <p style={s.heroSub}>
          Premium health foods, supplements, and snacks.
        </p>
      </div>

      {/* BODY */}
      <div style={s.shopBody}>
        {/* SEARCH + FILTER */}
        <div style={s.controls}>
          <input
            style={s.searchInput}
            placeholder="Search products..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />

          <div style={s.chips}>
            {CATEGORIES.map((c) => (
              <button
                key={c}
                style={category === c ? s.chipActive : s.chip}
                onClick={() => setCategory(c)}
              >
                {c}
              </button>
            ))}
          </div>
        </div>

        {/* PRODUCTS */}
        <div style={s.grid}>
          {filtered.map((p) => (
            <div
              key={p.productID}
              style={s.card}
            >
              <img
                src={getImage(p)}
                alt={p.productName}
                style={s.img}
                onError={(e) => {
                  e.target.src =
                    "https://images.unsplash.com/photo-1542838132-92c53300491e?w=600&q=80";
                }}
              />

              <div style={s.cardBody}>
                <span style={s.catTag}>{p.category}</span>

                <div style={s.productName}>
                  {p.productName}
                </div>

                <div style={s.brand}>{p.brand}</div>

                <div style={s.price}>
                  ₹{Number(p.price).toFixed(2)}
                </div>

                <div style={s.cardBtns}>
                  <button
                    style={s.viewBtn}
                    onClick={() =>
                      navigate(`/product/${p.productID}`)
                    }
                  >
                    View Details
                  </button>

                  <button
                    style={s.addBtn}
                    onClick={() => addToCart(p)}
                  >
                    + Cart
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
